CREATE OR REPLACE FUNCTION order_rev_fence() RETURNS trigger AS $$
BEGIN
  -- The @fenced counter Order.revision (D118):
  -- an update that changes a column it covers sets it to the stored value
  -- plus one, and any other keeps it or adds one.
  IF ROW(NEW.note, NEW.customer_id) IS DISTINCT FROM ROW(OLD.note, OLD.customer_id) THEN
    IF NEW.rev IS DISTINCT FROM OLD.rev + 1 THEN
      RAISE EXCEPTION 'order.rev must advance from % to %, not to %', OLD.rev, OLD.rev + 1, NEW.rev
        USING ERRCODE = 'check_violation', CONSTRAINT = 'order_rev_fence';
    END IF;
  ELSIF NEW.rev IS DISTINCT FROM OLD.rev THEN
    IF NEW.rev IS DISTINCT FROM OLD.rev + 1 THEN
      RAISE EXCEPTION 'order.rev must stay at % or advance to %, not move to %', OLD.rev, OLD.rev + 1, NEW.rev
        USING ERRCODE = 'check_violation', CONSTRAINT = 'order_rev_fence';
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql
